 const previews=useMemo(()=>form.data.uploads.map(f=>({file:f,src:URL.createObjectURL(f)})),[form.data.uploads]);useEffect(()=>()=>previews.forEach(p=>URL.revokeObjectURL(p.src)),[previews]);
