 function move(index,step){setPhotos(a=>{const next=[...a],target=index+step;if(target<0||target>=a.length)return a;[next[index],next[target]]=[next[target],next[index]];return next;});}
 function patchPhoto(id,values){setPhotos(a=>a.map(p=>p.id===id?{...p,...values}:p));}
 function save(e){e.preventDefault();form.transform(d=>({...d,...(car?{_method:'put'}:{}),features:d.features.split('\n').map(x=>x.trim()).filter(Boolean),notes:d.notes.split('\n').map(x=>x.trim()).filter(Boolean),attractions:d.attractions.filter(a=>a.label.trim()||a.value.trim()),performance_source:d.performance_url?{title:d.performance_title||'Model performance reference',url:d.performance_url}:null,photo_order:photos.filter(p=>!remove.includes(p.id)).map(p=>p.id),remove_photo_ids:remove,photo_updates:photos.map(p=>({id:p.id,alt:p.alt,description:p.description,object_position:p.objectPosition}))}));form.post(car?url(car):'/admin/cars',{forceFormData:true,preserveScroll:true,onSuccess:()=>form.setData('uploads',[])});}
 return <AdminLayout title={car?'Edit '+car.name:'Add to the collection'} eyebrow={car?'Cars':'New car'} subtitle={car?'Changes appear on the website as soon as you save.':'Fill in the details, add photographs and choose when it goes live.'} action={<div className="flex flex-wrap gap-3"><Link className="admin-action admin-secondary" href="/admin/cars">← All cars</Link><button type="submit" form="car-form" className="admin-action" disabled={form.processing}>{form.processing?'Saving…':car?'Update car':'Save car'}</button></div>}><form id="car-form" onSubmit={save} encType="multipart/form-data"><div className="grid items-start gap-6 xl:grid-cols-[1fr_300px]"><div className="flex min-w-0 flex-col gap-6"><section className="admin-panel"><p className="admin-kicker">01 · Details</p><h2 className="mb-5 !font-display !text-3xl">The essentials</h2><div className="grid gap-5 sm:grid-cols-2"><label className="admin-field sm:col-span-2"><span className="admin-label">Category</span><select className="admin-input" name="category_id" value={form.data.category_id} onChange={e=>form.setData('category_id',e.target.value)}><option value="">No category</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><span className="text-xs text-[#586153]">Customers can filter the catalogue by category. <Link href="/admin/categories" className="underline">Manage categories</Link></span>{error('category_id')}</label>{fields.map(([key,label,placeholder])=>input(key,label,placeholder,['year','mileage','price','import_year','import_mileage'].includes(key)?'number':'text'))}</div><div className="mt-5">{car?<p className="text-xs text-[#586153]">Permanent listing address: <a href={car.public_url} target="_blank" rel="noopener">{car.public_url}</a></p>:input('slug','Listing address (optional)','e.g. mercedes-e200-2023')}<p className="mt-2 text-xs text-[#586153]">An address is generated from the name and year if left blank. Existing addresses are kept so shared links continue working.</p></div></section><section className="admin-panel"><p className="admin-kicker">02 · Story</p><h2 className="mb-5 !font-display !text-3xl">What makes it right</h2><div className="grid gap-5">{area('best_for','Ideal buyer — a short line','Shown below the photograph on the inventory card.')}{area('usp','Standout feature','A separate highlight for what makes this car special.')}{area('features','Equipment','One feature per line.')}{area('notes','Additional notes','One note per line.')}</div></section><section className="admin-panel"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p className="admin-kicker">03 · Highlights</p><h2 className="!font-display !text-3xl">Car attractions</h2></div><button type="button" className="admin-action admin-secondary" onClick={()=>form.setData('attractions',[...form.data.attractions,{label:'',value:'',manufacturer:false}])}>Add a fact +</button></div><p className="mb-5 text-sm text-[#586153]">Engine, acceleration, range or another advertised highlight. Include a reference when quoting manufacturer performance figures.</p><div className="flex flex-col gap-5">{form.data.attractions.map((a,i)=><div key={i} className="rounded-lg bg-mist/50 p-4"><div className="grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><input aria-label={'Fact '+(i+1)+' label'} className="admin-input" placeholder="e.g. 0–100 km/h" value={a.label} onChange={e=>form.setData('attractions',form.data.attractions.map((x,j)=>j===i?{...x,label:e.target.value}:x))}/><input aria-label={'Fact '+(i+1)+' value'} className="admin-input" placeholder="e.g. 5.2 seconds" value={a.value} onChange={e=>form.setData('attractions',form.data.attractions.map((x,j)=>j===i?{...x,value:e.target.value}:x))}/><button type="button" className="admin-action admin-secondary" aria-label={'Remove fact '+(i+1)} onClick={()=>form.setData('attractions',form.data.attractions.filter((_,j)=>j!==i))}>Remove</button></div><label className="mt-3 flex items-center gap-2 text-xs"><input type="checkbox" checked={Boolean(a.manufacturer)} onChange={e=>form.setData('attractions',form.data.attractions.map((x,j)=>j===i?{...x,manufacturer:e.target.checked}:x))}/>Manufacturer model figure</label></div>)}</div><div className="mt-5 grid gap-5 sm:grid-cols-2">{input('performance_title','Reference title')}{input('performance_url','Performance reference URL','','url')}</div><div className="mt-5">{area('performance_note','Performance note (optional)')}</div></section><section className="admin-panel"><p className="admin-kicker">04 · Gallery</p><h2 className="mb-3 !font-display !text-3xl">Photographs</h2><p className="mb-5 text-sm text-[#586153]">The first photo is the cover. Move photos into order, add descriptions and adjust their framing. JPEG, PNG or WebP, up to 10 MB each. Upload up to 12 photos per save; 30 photographs per car.</p><label className={'admin-dropzone'+(dragging?' is-dragging':'')} onDragOver={e=>{e.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);form.setData('uploads',[...e.dataTransfer.files].filter(f=>/^image\/(jpeg|png|webp)$/.test(f.type)).slice(0,12));}}><input type="file" name="uploads[]" accept="image/jpeg,image/png,image/webp" multiple className="sr-only" onChange={e=>form.setData('uploads',[...e.target.files])}/><span className="admin-dropzone-icon"><NavIcon name="upload"/></span><span className="font-medium">{form.data.uploads.length?plural(form.data.uploads.length,'photo')+' ready to upload':'Drop photographs here'}</span><span className="text-xs text-[#586153]">JPEG, PNG or WebP · up to 12 at a time · uploaded when you save. Export HEIC photos as JPEG first.</span><span className="admin-dropzone-button">Browse files</span></label>{error('uploads')}{previews.length>0&&<div className="mt-5 grid grid-cols-2 gap-4 sm:grid-cols-3">{previews.map((p,i)=><figure key={p.src}><img className="aspect-[4/3] w-full rounded-[10px] object-cover" src={p.src} alt={'New upload '+(i+1)} loading="lazy" decoding="async"/><figcaption className="mt-2 break-all text-xs">{p.file.name} · ready to upload</figcaption></figure>)}</div>}<div className="mt-6 flex flex-col gap-5">{photos.map((p,i)=><div className={'grid gap-4 rounded-xl bg-mist/40 p-4 sm:grid-cols-[160px_1fr]'+(remove.includes(p.id)?' opacity-50':'')} key={p.id} data-admin-photo={p.id}><div><img className="aspect-[4/3] w-full rounded-[10px] object-cover" src={p.small} alt={p.alt} loading="lazy" decoding="async" style={{objectPosition:p.objectPosition}}/><div className="mt-3 flex flex-wrap gap-2"><button type="button" className="admin-nav-link !min-h-10 !bg-white !px-3" disabled={i===0} aria-label={'Move photograph '+(i+1)+' earlier'} onClick={()=>move(i,-1)}>↑</button><button type="button" className="admin-nav-link !min-h-10 !bg-white !px-3" disabled={i===photos.length-1} aria-label={'Move photograph '+(i+1)+' later'} onClick={()=>move(i,1)}>↓</button><span className="admin-status">{i===0?'Cover':'Photo '+(i+1)}</span></div></div><div className="grid gap-3"><label className="admin-field"><span>Description</span><input className="admin-input" value={p.description} onChange={e=>patchPhoto(p.id,{description:e.target.value})}/></label><label className="admin-field"><span>Accessible image description</span><input className="admin-input" value={p.alt} onChange={e=>patchPhoto(p.id,{alt:e.target.value})}/></label><label className="admin-field"><span>Vertical framing — keep the bumper and plate visible</span><input type="range" min="0" max="100" value={parseInt((p.objectPosition||'50% 65%').split(' ')[1])} onChange={e=>patchPhoto(p.id,{objectPosition:'50% '+e.target.value+'%'})}/></label><label className="flex items-center gap-2 text-sm text-red-800"><input type="checkbox" checked={remove.includes(p.id)} onChange={e=>setRemove(a=>e.target.checked?[...a,p.id]:a.filter(x=>x!==p.id))}/>Remove this photo when saved</label></div></div>)}</div></section><section className="admin-panel">{input('source_url','Original listing or source URL (optional)','','url')}</section></div><aside className="admin-panel admin-publish xl:sticky xl:top-6"><p className="admin-kicker">Go live</p><h2 className="mb-5 !font-display !text-3xl">Publishing</h2><label className="admin-field"><span className="admin-label">Listing status</span><select className="admin-input" name="status" value={form.data.status} onChange={e=>{form.setData('status',e.target.value);if(e.target.value!=='available')form.setData('is_featured',false);}}><option value="draft">Draft — private</option><option value="available">Available — publish</option><option value="sold">Sold — show sold tag</option></select></label><p className="mt-3 text-xs text-[#586153]">Available and sold records appear in the catalogue. Sold cars retain their detail pages and appear in Recently sold.</p><label className="mt-6 flex items-center gap-3 text-sm"><input type="checkbox" name="is_featured" checked={form.data.is_featured} disabled={form.data.status!=='available'} onChange={e=>form.setData('is_featured',e.target.checked)}/>Feature on the homepage</label><p className="mt-2 text-xs text-[#586153]">Selected available cars appear in the featured carousel. The approved filmed showroom hero stays unchanged.</p><div className="mt-5">{input('featured_order','Homepage order — lower numbers appear first','','number')}</div><div className="mt-6 flex flex-col gap-3"><button className="admin-action" disabled={form.processing}>{form.processing?'Saving…':car?'Update car':'Save car'} <Icon/></button>{form.progress&&<p className="text-sm" role="status">Uploading {form.progress.percentage}%</p>}{car&&car.status!=='draft'&&<a className="admin-action admin-secondary" href={car.public_url} target="_blank" rel="noopener">View listing ↗</a>}</div>{Object.keys(form.errors).length>0&&<div className="mt-5 rounded-lg bg-red-50 p-4 text-sm text-red-900" role="alert"><p className="mb-2 font-semibold">Review these details:</p><ul className="list-disc pl-4">{Object.entries(form.errors).map(([k,v])=><li key={k}>{v}</li>)}</ul></div>}{car&&<button type="button" className="admin-action admin-danger mt-8 w-full" onClick={()=>removeCar(car)}>Delete car</button>}</aside></div></form></AdminLayout>;
