const joined=value=>new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
// Mirrors Laravel's Password::min(12)->mixedCase()->numbers()->symbols() so the form shows what is still missing.
const passwordRules=[['At least 12 characters',p=>[...p].length>=12],['Uppercase and lowercase letters',p=>/\p{Lu}/u.test(p)&&/\p{Ll}/u.test(p)],['A number',p=>/\p{N}/u.test(p)],['A symbol, e.g. ! @ # -',p=>/[\p{Z}\p{S}\p{P}]/u.test(p)]];
function generatePassword(){const sets=['ABCDEFGHJKLMNPQRSTUVWXYZ','abcdefghijkmnopqrstuvwxyz','23456789','!@#$%&*?-_'],random=n=>crypto.getRandomValues(new Uint32Array(1))[0]%n,chars=sets.map(s=>s[random(s.length)]),all=sets.join('');while(chars.length<16)chars.push(all[random(all.length)]);for(let i=chars.length-1;i>0;i--){const j=random(i+1);[chars[i],chars[j]]=[chars[j],chars[i]];}return chars.join('');}
function PasswordChecklist({password,confirmation}){if(!password)return null;const rows=[...passwordRules.map(([label,test])=>[label,test(password)]),...(confirmation?[['Both passwords match',password===confirmation]]:[])];return <ul className="flex flex-col gap-1 text-xs" aria-label="Password requirements">{rows.map(([label,ok])=><li key={label} className={ok?'text-forest':'text-[#8e2424]'}><span aria-hidden="true">{ok?'✓':'✗'}</span> {label}<span className="sr-only">{ok?' (done)':' (missing)'}</span></li>)}</ul>;}
function Avatar({user,size=40}){const initials=(user?.name||'').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()||'?';return user?.avatar_url?<img src={user.avatar_url} width={size} height={size} alt="" className="shrink-0 rounded-full object-cover" style={{width:size,height:size}}/>:<span className="admin-avatar" style={{width:size,height:size,fontSize:Math.round(size*.38)}} aria-hidden="true">{initials}</span>;}
// Chooses, previews or removes a profile photo; the file itself is sent with the surrounding form.
function PhotoPicker({name,current,file,remove,onFile,onRemove,error}){
 const preview=useMemo(()=>file?URL.createObjectURL(file):null,[file]);useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview);},[preview]);
 const shown=preview||(!remove&&current)||null;
 return <div className="admin-field"><span className="admin-label">Profile photo</span><div className="flex items-center gap-4"><Avatar user={{name,avatar_url:shown}} size={72}/><div className="flex min-w-0 flex-col items-start gap-1"><label className="admin-action admin-secondary !min-h-9 cursor-pointer !px-4 focus-within:ring-2 focus-within:ring-forest/30"><input type="file" className="sr-only" accept="image/jpeg,image/png,image/webp" onChange={e=>{onFile(e.target.files[0]||null);e.target.value='';}}/>{shown?'Change photo':'Add photo'}</label>{shown&&<button type="button" className="admin-link-button" onClick={()=>file?onFile(null):onRemove(true)}>Remove photo</button>}{remove&&!file&&current&&<button type="button" className="admin-link-button" onClick={()=>onRemove(false)}>Keep current photo</button>}</div></div><span className="text-xs text-[#586153]">JPEG, PNG or WebP up to 5 MB. It is cropped to a square.</span>{error}</div>;
}
function Users(){
 const {users,errors}=usePage().props,blank={name:'',email:'',password:'',password_confirmation:'',is_active:true,avatar:null,remove_avatar:false},form=useForm(blank),[editing,setEditing]=useState(null),[show,setShow]=useState(false);
 const error=key=>form.errors[key]&&<p className="admin-error" role="alert">{form.errors[key]}</p>,pageError=form.errors.user||errors?.user;
 function edit(u){setEditing(u);setShow(false);form.clearErrors();form.setData({name:u.name,email:u.email,password:'',password_confirmation:'',is_active:u.is_active,avatar:null,remove_avatar:false});}
 function cancel(){setEditing(null);setShow(false);form.clearErrors();form.setData(blank);}
 function generate(){const p=generatePassword();form.setData(d=>({...d,password:p,password_confirmation:p}));setShow(true);}
 function save(e){e.preventDefault();form.transform(d=>editing?{...d,_method:'put'}:d);form.post(editing?'/admin/users/'+editing.id:'/admin/users',{forceFormData:true,preserveScroll:true,onSuccess:cancel});}
 function destroy(u){if(window.confirm('Delete the user '+u.name+' ('+u.email+')? They will be signed out and can no longer sign in.'))router.delete('/admin/users/'+u.id,{preserveScroll:true,onSuccess:()=>{if(editing?.id===u.id)cancel();}});}
 function makeAdmin(u){if(window.confirm('Make '+u.name+' the Admin? There is only one Admin, so your own account will become a User and you will lose access to this page.'))router.post('/admin/users/'+u.id+'/make-admin');}
 return <AdminLayout title="Users" eyebrow="Who can sign in" subtitle="Add the people who work on the showroom, reset passwords and choose the Admin."><div className="grid items-start gap-6 lg:grid-cols-[380px_1fr]"><form className="admin-panel lg:sticky lg:top-6" onSubmit={save} autoComplete="off"><h2 className="mb-2 !font-display !text-3xl">{editing?(editing.is_you?'Edit your account':'Edit user'):'Add a user'}</h2><p className="mb-5 text-sm text-[#586153]">{editing?.is_you?'You are the Admin.':'Users can add, edit and delete cars and categories. Only the Admin manages users.'}</p><div className="flex flex-col gap-5"><PhotoPicker name={form.data.name} current={editing?.avatar_url} file={form.data.avatar} remove={form.data.remove_avatar} onFile={f=>form.setData(d=>({...d,avatar:f,remove_avatar:false}))} onRemove={v=>form.setData('remove_avatar',v)} error={error('avatar')}/><label className="admin-field"><span className="admin-label">Full name</span><input className="admin-input" name="name" required maxLength="120" value={form.data.name} onChange={e=>form.setData('name',e.target.value)}/>{error('name')}</label><label className="admin-field"><span className="admin-label">Email address</span><input className="admin-input" type="email" name="email" required maxLength="254" autoComplete="off" value={form.data.email} onChange={e=>form.setData('email',e.target.value)}/>{error('email')}</label><div className="flex flex-col gap-1"><PasswordField label={editing?'New password (optional)':'Password'} name="password" show={show} onToggle={()=>setShow(v=>!v)} required={!editing} autoComplete="new-password" placeholder={editing?'leave blank to keep the current one':''} value={form.data.password} onChange={e=>form.setData('password',e.target.value)}>{error('password')}</PasswordField><button type="button" className="admin-link-button self-start" onClick={generate}>Generate a strong password</button></div><PasswordField label="Confirm password" name="password_confirmation" show={show} onToggle={()=>setShow(v=>!v)} required={!editing||Boolean(form.data.password)} autoComplete="new-password" value={form.data.password_confirmation} onChange={e=>form.setData('password_confirmation',e.target.value)}/><PasswordChecklist password={form.data.password} confirmation={form.data.password_confirmation}/>{show&&form.data.password&&<p className="text-xs text-[#586153]">Share the password with the user privately, in person or by phone.</p>}<label className="flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1" checked={form.data.is_active} disabled={editing?.is_you} onChange={e=>form.setData('is_active',e.target.checked)}/><span>Can sign in<span className="block text-xs text-[#586153]">{editing?.is_you?'You cannot turn off your own sign-in.':'Turn off to block sign-in without deleting the user.'}</span></span></label>{pageError&&<p className="admin-error" role="alert">{pageError}</p>}<div className="flex flex-wrap gap-3"><button className="admin-action" disabled={form.processing}>{form.processing?'Saving…':editing?'Update user':'Create user'}</button>{editing&&<button type="button" className="admin-action admin-secondary" onClick={cancel}>Cancel</button>}</div>{form.progress&&<p className="text-sm" role="status">Uploading {form.progress.percentage}%</p>}</div></form><section className="admin-panel"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 className="!font-display !text-3xl">All users</h2><p className="text-sm text-[#586153]">{plural(users.length,'account')} · one Admin</p></div><div className="overflow-x-auto"><table className="admin-table"><thead><tr><th>Name</th><th>Access</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{users.map(u=><tr key={u.id} data-admin-user={u.id} className={editing?.id===u.id?'bg-mist/50':undefined}><td><div className="flex items-center gap-3"><Avatar user={u} size={44}/><div className="min-w-0"><p className="font-medium">{u.name}{u.is_you&&<span className="admin-status ml-2 !bg-white">You</span>}</p><p className="text-xs text-[#586153] [overflow-wrap:anywhere]">{u.email}</p><p className="text-xs text-[#7f8a7a]">Added {joined(u.created_at)}</p></div></div></td><td data-label="Access"><div className="flex flex-wrap gap-1.5">{u.is_admin?<span className="admin-status !bg-forest !text-white">Admin</span>:<span className="admin-status">User</span>}{u.is_active?<span className="admin-status !bg-[#e6eedf]">Active</span>:<span className="admin-status !bg-gray-200 !text-[#586153]">Sign-in off</span>}</div></td><td><div className="admin-row-actions"><button type="button" className="admin-action admin-secondary !min-h-9 !px-4" aria-label={'Edit '+u.name} onClick={()=>edit(u)}>Edit</button>{!u.is_admin&&<>{u.is_active&&<button type="button" className="admin-action admin-secondary !min-h-9 !px-4" aria-label={'Make '+u.name+' the Admin'} onClick={()=>makeAdmin(u)}>Make admin</button>}<button type="button" className="admin-action admin-danger !min-h-9 !px-4" aria-label={'Delete '+u.name} onClick={()=>destroy(u)}>Delete</button></>}</div></td></tr>)}</tbody></table></div></section></div></AdminLayout>;
}
function Profile(){
 const {profile}=usePage().props,details=useForm({name:profile.name,avatar:null,remove_avatar:false}),pass=useForm({current_password:'',password:'',password_confirmation:''}),[show,setShow]=useState(false);
 const error=(form,key)=>form.errors[key]&&<p className="admin-error" role="alert">{form.errors[key]}</p>;
 function saveDetails(e){e.preventDefault();details.transform(d=>({...d,_method:'put'}));details.post('/admin/profile',{forceFormData:true,preserveScroll:true,onSuccess:()=>details.setData(d=>({...d,avatar:null,remove_avatar:false}))});}
 function savePassword(e){e.preventDefault();pass.put('/admin/profile/password',{preserveScroll:true,onSuccess:()=>{pass.reset();setShow(false);},onError:()=>pass.reset('current_password')});}
 return <AdminLayout title="My profile" bare><section className="admin-profile-cover"><Avatar user={profile} size={96}/><div className="min-w-0"><p className="admin-kicker">My profile · {profile.is_admin?'Admin':'User'}</p><h1 className="admin-page-title">{profile.name}</h1><p className="admin-page-sub [overflow-wrap:anywhere]">{profile.email} · joined {joined(profile.created_at)}</p></div></section><div className="grid items-start gap-6 lg:grid-cols-2"><form className="admin-panel" onSubmit={saveDetails}><h2 className="mb-5 !font-display !text-3xl">Your details</h2><div className="flex flex-col gap-5"><PhotoPicker name={details.data.name} current={profile.avatar_url} file={details.data.avatar} remove={details.data.remove_avatar} onFile={f=>details.setData(d=>({...d,avatar:f,remove_avatar:false}))} onRemove={v=>details.setData('remove_avatar',v)} error={error(details,'avatar')}/><label className="admin-field"><span className="admin-label">Full name</span><input className="admin-input" name="name" required maxLength="120" value={details.data.name} onChange={e=>details.setData('name',e.target.value)}/>{error(details,'name')}</label><div className="admin-field"><span className="admin-label">Email address</span><p className="admin-input !bg-mist/40 break-all">{profile.email}</p><span className="text-xs text-[#586153]">{profile.is_admin?'Change your email from the Users page.':'Only the Admin can change your email.'}</span></div><div className="admin-field"><span className="admin-label">Access</span><p className="text-sm text-[#586153]">{profile.is_admin?'Admin: you can add, edit and delete cars, categories and users.':'User: you can add, edit and delete cars and categories. Only the Admin manages users.'}</p></div><button className="admin-action self-start" disabled={details.processing}>{details.processing?'Saving…':'Save profile'}</button></div></form><form className="admin-panel" onSubmit={savePassword} autoComplete="off"><h2 className="mb-5 !font-display !text-3xl">Change password</h2><div className="flex flex-col gap-5"><PasswordField label="Current password" name="current_password" required autoComplete="current-password" show={show} onToggle={()=>setShow(v=>!v)} value={pass.data.current_password} onChange={e=>pass.setData('current_password',e.target.value)}>{error(pass,'current_password')}</PasswordField><PasswordField label="New password" name="password" required autoComplete="new-password" show={show} onToggle={()=>setShow(v=>!v)} value={pass.data.password} onChange={e=>pass.setData('password',e.target.value)}>{error(pass,'password')}</PasswordField><PasswordField label="Confirm new password" name="password_confirmation" required autoComplete="new-password" show={show} onToggle={()=>setShow(v=>!v)} value={pass.data.password_confirmation} onChange={e=>pass.setData('password_confirmation',e.target.value)}/><PasswordChecklist password={pass.data.password} confirmation={pass.data.password_confirmation}/><p className="text-xs text-[#586153]">Changing your password signs you out on your other devices.</p><button className="admin-action self-start" disabled={pass.processing}>{pass.processing?'Saving…':'Change password'}</button></div></form></div></AdminLayout>;
}
// The Admin connects the mailbox that emails website enquiries. The server detects the provider from the email's domain unless set under Advanced.
function MailSettings(){
 const {settings,errors}=usePage().props,automatic=settings?.automatic??true;
 const form=useForm({email:settings?.email||'',password:'',recipient:settings?.recipient||'',host:automatic?'':settings.host,port:automatic?'':settings.port,security:automatic?'':settings.security,is_enabled:settings?.is_enabled??true}),[show,setShow]=useState(false),[advanced,setAdvanced]=useState(!automatic),[testing,setTesting]=useState(false),[provider,setProvider]=useState(null);
 useEffect(()=>{const email=form.data.email.trim();setProvider(null);if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return;const controller=new AbortController(),timer=setTimeout(()=>fetch('/admin/mail/provider?email='+encodeURIComponent(email),{headers:{Accept:'application/json'},signal:controller.signal}).then(r=>r.ok?r.json():null).then(setProvider).catch(()=>{}),400);return()=>{clearTimeout(timer);controller.abort();};},[form.data.email]);
 const gmail=(form.data.host||provider?.host)==='smtp.gmail.com',inbox=settings?.recipient||settings?.email;
 const error=key=>form.errors[key]&&<p className="admin-error" role="alert">{form.errors[key]}</p>;
 function save(e){e.preventDefault();form.put('/admin/mail',{preserveScroll:true,onSuccess:()=>{form.setData('password','');form.setDefaults();}});}
 function test(){router.post('/admin/mail/test',{},{preserveScroll:true,onStart:()=>setTesting(true),onFinish:()=>setTesting(false)});}
 const status=!settings?['Not connected','Add an email and password to receive website enquiries by email.','!bg-gray-200']:settings.is_enabled?['Connected','Enquiries are emailed to '+inbox+'.','']:['Turned off','Enquiries are not emailed. Customers still continue to WhatsApp.','!bg-[#ded4c3]'];
 return <AdminLayout title="Email" eyebrow="Website enquiries" subtitle="Connect an email account so viewing requests and sell or trade-in enquiries from the website arrive in your inbox."><div className="grid items-start gap-6 lg:grid-cols-[1fr_360px]"><form className="admin-panel" onSubmit={save} autoComplete="off"><h2 className="mb-5 !font-display !text-3xl">Email account</h2><div className="flex flex-col gap-5">
  <label className="admin-field"><span className="admin-label">Email address</span><input className="admin-input" name="email" type="email" required maxLength="190" autoComplete="off" placeholder="e.g. samautomobiles@gmail.com" value={form.data.email} onChange={e=>form.setData('email',e.target.value)}/>{provider&&<span className="text-xs text-[#586153]">Detected: {provider.name} · {form.data.host||provider.host}</span>}{error('email')}</label>
  <PasswordField label={gmail?'Gmail App Password':'Email password'} name="password" required={!settings} autoComplete="new-password" placeholder={settings?.has_password?'Saved. Leave blank to keep it':''} show={show} onToggle={()=>setShow(v=>!v)} value={form.data.password} onChange={e=>form.setData('password',e.target.value)}>{gmail&&<span className="text-xs text-[#586153]">Gmail needs an App Password, not your normal password. Turn on 2-Step Verification, then create one at <a className="underline" href="https://myaccount.google.com/apppasswords" target="_blank" rel="noopener">myaccount.google.com/apppasswords</a> and paste its 16 letters here.</span>}{error('password')}</PasswordField>
  <label className="admin-field"><span className="admin-label">Send enquiries to (optional)</span><input className="admin-input" name="recipient" type="email" maxLength="190" placeholder={form.data.email||'Same as the email above'} value={form.data.recipient} onChange={e=>form.setData('recipient',e.target.value)}/><span className="text-xs text-[#586153]">Leave blank to receive enquiries at the email above.</span>{error('recipient')}</label>
  <label className="flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1" checked={form.data.is_enabled} onChange={e=>form.setData('is_enabled',e.target.checked)}/><span>Email website enquiries<span className="block text-xs text-[#586153]">Turn off to stop emails without removing these settings.</span></span></label>
  <div className="admin-field"><button type="button" className="self-start text-sm underline" aria-expanded={advanced} onClick={()=>setAdvanced(v=>!v)}>{advanced?'Hide advanced settings':'Advanced settings'}</button>{advanced&&<div className="mt-3 grid gap-4 sm:grid-cols-[1fr_110px_130px]"><label className="admin-field"><span className="admin-label">SMTP server</span><input className="admin-input" name="host" maxLength="190" placeholder={provider?.host||''} value={form.data.host} onChange={e=>form.setData('host',e.target.value)}/>{error('host')}</label><label className="admin-field"><span className="admin-label">Port</span><input className="admin-input" name="port" type="number" min="1" max="65535" placeholder={provider?String(provider.port):''} value={form.data.port} onChange={e=>form.setData('port',e.target.value)}/>{error('port')}</label><label className="admin-field"><span className="admin-label">Security</span><select className="admin-input" name="security" value={form.data.security} onChange={e=>form.setData('security',e.target.value)}><option value="">Automatic{provider?' ('+provider.security.toUpperCase()+')':''}</option><option value="ssl">SSL</option><option value="tls">TLS</option></select>{error('security')}</label><p className="text-xs text-[#586153] sm:col-span-3">Leave these blank to use the usual settings for {provider?.name||'this email'}.</p></div>}</div>
  <button className="admin-action self-start" disabled={form.processing}>{form.processing?'Saving…':'Save email settings'}</button></div></form>
  <aside className="admin-panel lg:sticky lg:top-6"><h2 className="mb-4 !font-display !text-3xl">Status</h2><span className={'admin-status '+status[2]}>{status[0]}</span><p className="mt-3 text-sm text-[#586153] [overflow-wrap:anywhere]">{status[1]}</p>{errors?.mail&&<p className="admin-error mt-4" role="alert">{errors.mail}</p>}<button type="button" className="admin-action admin-secondary mt-5" disabled={!settings||testing||form.isDirty} onClick={test}>{testing?'Sending…':'Send test email'}</button>{form.isDirty&&settings&&<p className="mt-2 text-xs text-[#586153]">Save your changes before sending a test.</p>}<p className="mt-6 text-sm text-[#586153]">Each enquiry email includes the customer’s name, mobile number, the car and their message. Sell and trade-in photos are attached. Nothing is stored on the website, and customers still continue to WhatsApp.</p></aside></div></AdminLayout>;
}
const pages={'Admin/Mail':MailSettings,'Admin/Login':Login,'Admin/Dashboard':Dashboard,'Admin/Inventory':Inventory,'Admin/CarEditor':CarEditor,'Admin/Categories':Categories,'Admin/Users':Users,'Admin/Profile':Profile};
export default function AdminApp(){const Page=pages[usePage().component]||Dashboard;return <Page/>;}
